/// <summary>What a person writes to make a note. Attributes here are checked before the handler runs.</summary>
public sealed record NewNote(
    [property: Required, StringLength(Note.TitleMax, MinimumLength = 1)] string Title,
    [property: StringLength(Note.BodyMax)] string? Body);

import { api, BudgetExhaustedError, NotSignedInError, signInUrl, ValidationError } from "@endgame/appkit";

try {
  await api("notes", { method: "POST", body: { title, body } });
} catch (e) {
  if (e instanceof ValidationError) setFieldErrors(e.errors); // { Title: ["The Title field is required."] }
  else if (e instanceof NotSignedInError) location.assign(e.signInUrl ?? signInUrl());
  else if (e instanceof BudgetExhaustedError) setNotice(e.message);
  else throw e;
}

const notes = useApiQuery<NoteSummary[]>("notes");

{notes.status === "loading" && <LoadingState label="Loading notes…" />}
{notes.status === "failed" && <FailedState error={notes.error} onRetry={notes.reload} />}
{notes.status === "loaded" && notes.data.length === 0 && <EmptyState title="No notes yet" />}

await api("/notes");
await api("api/notes");
await api("https://example.com/notes");
